//! Service for ingesting entity search data
//!

use crate::domain::{
    models::entity_ingestion::{
        DeclarationIngestionStage, EntityIngestionError, EntityIngestionRequest,
        EntityIngestionTarget,
    },
    repositories::{
        entity_ingestion_pipline::EntityIngestionStorage, parliament_api::ParliamentApi,
    },
    services::entity_ingestion::interface::EntitySearchIngestionService,
};

mod interface;

/// Allows users to search the databse using free text.
#[derive(Clone)]
pub struct Service<PS, PA> {
    pipeline_storage: PS,
    parliament_api: PA,
}

impl<PS, PA> Service<PS, PA> {
    /// Creates a new instance
    pub const fn new(pipeline_storage: PS, parliament_api: PA) -> Self {
        Self {
            pipeline_storage,
            parliament_api,
        }
    }
}

impl<PS, PA> EntitySearchIngestionService for Service<PS, PA>
where
    PS: EntityIngestionStorage,
    PA: ParliamentApi,
{
    /// Returns text search results for MPs and Funder entities.
    ///
    /// This function expects the repositories to return their results
    /// in order where a higher score means a higher similarity.
    async fn run_ingestion(
        &self,
        req: &EntityIngestionRequest,
    ) -> Result<(), EntityIngestionError> {
        match req.target() {
            EntityIngestionTarget::Members => self.ingest_members().await,
            EntityIngestionTarget::Declaration(stage) => match stage {
                DeclarationIngestionStage::Import => self.ingest_declarations().await,
                DeclarationIngestionStage::Clean => self.clean_funders().await,
                DeclarationIngestionStage::Resolve => self.resolve_funders().await,
            },
        }
    }
}

impl<PS, PA> Service<PS, PA>
where
    PA: ParliamentApi,
{
    async fn fetch_members(&self) -> Result<(), EntityIngestionError> {
        self.parliament_api.get_sitting_members().await?;
        Ok(())
    }

    async fn fetch_declarations(&self) -> Result<(), EntityIngestionError> {
        self.parliament_api
            .get_declarations_for_sitting_members()
            .await?;
        Ok(())
    }
}

impl<PS, PA> Service<PS, PA>
where
    PS: EntityIngestionStorage,
    PA: ParliamentApi,
{
    async fn ingest_members(&self) -> Result<(), EntityIngestionError> {
        self.fetch_members().await?;
        self.pipeline_storage.write_raw_data().await?;
        Ok(())
    }

    async fn ingest_declarations(&self) -> Result<(), EntityIngestionError> {
        self.fetch_declarations().await?;
        self.pipeline_storage.write_raw_data().await?;
        Ok(())
    }
}

impl<PS, PA> Service<PS, PA>
where
    PS: EntityIngestionStorage,
{
    async fn clean_funders(&self) -> Result<(), EntityIngestionError> {
        self.pipeline_storage.read_raw_data().await?;
        self.pipeline_storage.write_cleaned_data().await?;
        Ok(())
    }

    async fn resolve_funders(&self) -> Result<(), EntityIngestionError> {
        self.pipeline_storage.read_cleaned_data().await?;
        self.pipeline_storage.write_resolved_data().await?;
        Ok(())
    }
}
//! Contains entity ingestion models

use std::str::FromStr;

use strum::EnumString;
use thiserror::Error;

use crate::domain::repositories::{
    entity_ingestion_pipline::EntitySearchPipelineError, parliament_api::ParliamentApiError,
};

/// Data required to search entities
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct EntityIngestionRequest {
    target: EntityIngestionTarget,
}

impl EntityIngestionRequest {
    pub fn new_members_request() -> Self {
        Self {
            target: EntityIngestionTarget::Members,
        }
    }
    pub fn new_declaration_request(stage: &str) -> Result<Self, EntityIngestionError> {
        let stage = DeclarationIngestionStage::from_str(stage)
            .map_err(|_| EntityIngestionError::InvalidStage(stage.to_string()))?;

        Ok(Self {
            target: EntityIngestionTarget::Declaration(stage),
        })
    }

    pub fn target(&self) -> &EntityIngestionTarget {
        &self.target
    }
}

/// Ingestion targets
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum EntityIngestionTarget {
    /// MPs
    Members,
    /// Declarations, funders, funding entries
    Declaration(DeclarationIngestionStage),
}

/// From what stage to run the declaration pipeline
#[derive(Clone, Debug, PartialEq, Eq, EnumString)]
#[allow(missing_docs)]
#[strum(ascii_case_insensitive)]
pub enum DeclarationIngestionStage {
    Import,
    Clean,
    Resolve,
}

/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntityIngestionError {
    /// Errors related to the parliament API
    #[error("error when retrieving data from the parliament API: {0}")]
    ApiError(#[from] ParliamentApiError),

    /// Generic error related to entity parsing, cleaning and resolution
    #[error("error in ingestion pipeline: {0}")]
    DataError(String),

    /// Invalid strictness value
    #[error("at least one entry must be expected to return")]
    IoError(#[from] EntitySearchPipelineError),

    /// Invalid stage
    #[error("invalid stage provided: {0}")]
    InvalidStage(String),
}
use thiserror::Error;

/// Set of I/O methods for data in the entity search pipeline
pub trait EntityIngestionStorage: Clone + Send + Sync + 'static {
    /// Reads raw data persisted from the parliament API    
    fn read_raw_data(&self) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Reads cleaned data
    fn read_cleaned_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Reads resolved data
    fn read_resolved_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes raw data pulled from the parliament API
    fn write_raw_data(&self) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes cleaned data pulled from the parliament API
    fn write_cleaned_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes resolved data pulled from the parliament API
    fn write_resolved_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
}

/// Errors that can occur when interacting with the repo
#[derive(Error, Debug)]
pub enum EntitySearchPipelineError {
    /// Error when reading pipeline results
    #[error("unable to read pipeline data due to {0}")]
    ReadError(String),
    /// Error when writing pipeline results
    #[error("unable to write pipeline data due to {0}")]
    WriteError(String),
}

