    target: EntityIngestionTarget,
}

impl EntityIngestionRequest {
    pub fn new_members_request() -> Self {
        Self {
            target: EntityIngestionTarget::Members,
        }
    }
    pub fn new_declaration_request(stage: &str) -> Result<Self, EntityIngestionError> {
        let stage = DeclarationIngestionStage::from_str(stage)
            .map_err(|_| EntityIngestionError::InvalidStage(stage.to_string()))?;

        Ok(Self {
            target: EntityIngestionTarget::Declaration(stage),
        })
    }

    pub fn target(&self) -> &EntityIngestionTarget {
        &self.target
    }
}

/// Ingestion targets
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum EntityIngestionTarget {
    /// MPs
    Members,
    /// Declarations, funders, funding entries
    Declaration(DeclarationIngestionStage),
}

/// From what stage to run the declaration pipeline
#[derive(Clone, Debug, PartialEq, Eq, EnumString)]
#[allow(missing_docs)]
#[strum(ascii_case_insensitive)]
pub enum DeclarationIngestionStage {
    Import,
    Clean,
    Resolve,
}

/// Errors related to entity search
#[derive(Error, Debug)]
pub enum EntityIngestionError {
    /// Errors related to the parliament API
    #[error("error when retrieving data from the parliament API: {0}")]
    ApiError(#[from] ParliamentApiError),

    /// Generic error related to entity parsing, cleaning and resolution
    #[error("error in ingestion pipeline: {0}")]
    DataError(String),

    /// Invalid strictness value
    #[error("at least one entry must be expected to return")]
    IoError(#[from] EntitySearchPipelineError),

    /// Invalid stage
    #[error("invalid stage provided: {0}")]
    InvalidStage(String),
}
use thiserror::Error;

/// Set of I/O methods for data in the entity search pipeline
pub trait EntityIngestionStorage: Clone + Send + Sync + 'static {
    /// Reads raw data persisted from the parliament API    
    fn read_raw_data(&self) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Reads cleaned data
    fn read_cleaned_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Reads resolved data
    fn read_resolved_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes raw data pulled from the parliament API
    fn write_raw_data(&self) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes cleaned data pulled from the parliament API
    fn write_cleaned_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
    /// Writes resolved data pulled from the parliament API
    fn write_resolved_data(
        &self,
    ) -> impl Future<Output = Result<(), EntitySearchPipelineError>> + Send;
}

/// Errors that can occur when interacting with the repo
#[derive(Error, Debug)]
pub enum EntitySearchPipelineError {
    /// Error when reading pipeline results
    #[error("unable to read pipeline data due to {0}")]
    ReadError(String),
    /// Error when writing pipeline results
    #[error("unable to write pipeline data due to {0}")]
    WriteError(String),
}
"}}

