struct FsSchema {
    raw: String,
    cleaned: String,
    resolved: String,
}

impl Default for FsSchema {
    fn default() -> Self {
        Self {
            raw: "raw".into(),
            cleaned: "cleaned".into(),
            resolved: "resolved".into(),
        }
    }
}

impl ExposedDataPipeline {
    /// Creates a new instance of [`ExposedDataPipeline`]
