  1	//! File system interface for entity search ingestion
  2	
  3	use std::path::{self, PathBuf};
  4	
  5	use chrono::{DateTime, Utc};
  6	
  7	#[derive(Clone)]
  8	pub struct ExposedDataPipeline {
  9	    root: PathBuf,
 10	    key: DateTime<Utc>,
 11	    fs_schema: FsSchema,
 12	}
 13	
 14	#[derive(Clone)]
 15	struct FsSchema {
 16	    raw: String,
 17	    cleaned: String,
 18	    resolved: String,
 19	}
 20	
 21	impl Default for FsSchema {
 22	    fn default() -> Self {
 23	        Self {
 24	            raw: "raw".into(),
 25	            cleaned: "cleaned".into(),
 26	            resolved: "resolved".into(),
 27	        }
 28	    }
 29	}
 30	
 31	impl ExposedDataPipeline {
 32	    /// Creates a new instance of [`ExposedDataPipeline`]
 33	    pub fn new_with_key(root: &PathBuf, key: DateTime<Utc>) -> Self {
 34	        let root_abs = path::absolute(root).expect("valid root path must be provided");
 35	        Self {
 36	            root: root_abs,
 37	            key,
 38	            fs_schema: FsSchema::default(),
 39	        }
 40	    }
 41	
 42	    fn latest_run_path(&self) -> PathBuf {
 43	        self.root.join(self.key.to_string())
 44	    }
 45	
 46	    pub(super) fn raw_path(&self) -> PathBuf {
 47	        self.latest_run_path().join(&self.fs_schema.raw)
 48	    }
 49	
 50	    pub(super) fn cleaned_path(&self) -> PathBuf {
 51	        self.latest_run_path().join(&self.fs_schema.cleaned)
 52	    }
 53	
 54	    pub(super) fn resolved_path(&self) -> PathBuf {
 55	        self.latest_run_path().join(&self.fs_schema.resolved)
 56	    }
 57	}
  1	use std::path::PathBuf;
  2	
  3	use clap::{Args, Parser, Subcommand};
  4	use exposed::{config::Config, inbound::http::server::serve_exposed};
  5	
  6	#[derive(Parser)]
  7	struct Cli {
  8	    #[command(subcommand)]
  9	    command: Commands,
 10	}
 11	
 12	#[derive(Subcommand)]
 13	enum Commands {
 14	    Server { config: PathBuf },
 15	    Data(DataArgs),
 16	}
 17	
 18	#[derive(Args)]
 19	struct DataArgs {
 20	    #[command(subcommand)]
 21	    command: DataCommands,
 22	}
 23	
 24	#[derive(Subcommand)]
 25	enum DataCommands {
 26	    Fetch { config: PathBuf },
 27	    Clean { config: PathBuf },
 28	    Resolve { config: PathBuf },
 29	}
 30	
 31	#[tokio::main]
 32	async fn main() -> anyhow::Result<()> {
 33	    let args = Cli::parse();
 34	
 35	    match args.command {
 36	        Commands::Server { config } => {
 37	            let config = Config::try_from(&config)?;
 38	            let _ = serve_exposed(&config).await?;
 39	        }
 40	        _ => panic!("only server commands supported"),
 41	    }
 42	
 43	    Ok(())
 44	}

